option.value:
.fo-root {
    -fx-background-color: linear-gradient(to bottom right, #f4f8ff, #eef6f2);
    -fx-font-family: "Segoe UI";
}

.fo-topbar {
    -fx-background-color: rgba(255,255,255,0.94);
    -fx-border-color: #e5ebf4;
    -fx-border-width: 0 0 1 0;
}

.fo-brand-title {
    -fx-font-size: 28px;
    -fx-font-weight: bold;
    -fx-text-fill: #17324d;
}

.fo-brand-subtitle {
    -fx-font-size: 13px;
    -fx-text-fill: #6e7d92;
}

.fo-nav-button {
    -fx-background-color: white;
    -fx-text-fill: #526173;
    -fx-background-radius: 16;
    -fx-border-radius: 16;
    -fx-border-color: #dfe7f2;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-padding: 11 18 11 18;
    -fx-cursor: hand;
}

.fo-nav-button:hover {
    -fx-background-color: #edf2ff;
    -fx-text-fill: #5d4df1;
}

.fo-nav-button-active {
    -fx-background-color: linear-gradient(to right, #6d5dfc, #5b4be9);
    -fx-border-color: transparent;
    -fx-text-fill: white;
}

.fo-user-chip {
    -fx-background-color: #e9faf2;
    -fx-background-radius: 999;
    -fx-padding: 10 16 10 16;
    -fx-text-fill: #118a58;
    -fx-font-weight: bold;
}

.fo-content-placeholder {
    -fx-padding: 30;
}

.fo-placeholder-title {
    -fx-font-size: 18px;
    -fx-font-weight: bold;
    -fx-text-fill: #243248;
}

.catalogue-page,
.history-page {
    -fx-padding: 24;
}

.hero-card {
    -fx-background-color: linear-gradient(to right, #163b5b, #1d694f);
    -fx-background-radius: 26;
    -fx-padding: 26;
}

.hero-title {
    -fx-font-size: 30px;
    -fx-font-weight: bold;
    -fx-text-fill: #243248;
}

.hero-card .hero-title {
    -fx-text-fill: white;
}

.hero-subtitle {
    -fx-font-size: 15px;
    -fx-text-fill: #718197;
}

.hero-card .hero-subtitle {
    -fx-text-fill: rgba(255,255,255,0.84);
}

.catalogue-scroll,
.history-scroll {
    -fx-background-color: transparent;
    -fx-background-insets: 0;
}

.catalogue-scroll > .viewport,
.history-scroll > .viewport {
    -fx-background-color: transparent;
}

.catalogue-list {
    -fx-padding: 2;
}

.product-card {
    -fx-background-color: white;
    -fx-background-radius: 22;
    -fx-border-color: #e7edf6;
    -fx-border-radius: 22;
    -fx-effect: dropshadow(gaussian, rgba(36,50,72,0.08), 20, 0, 0, 5);
}

.product-card-media {
    -fx-alignment: center;
    -fx-background-color: linear-gradient(to bottom right, #eff5ff, #dff2ea);
    -fx-background-radius: 18;
}

.product-card-media-label {
    -fx-font-size: 28px;
    -fx-font-weight: bold;
    -fx-text-fill: #5d4df1;
}

.product-card-title {
    -fx-font-size: 19px;
    -fx-font-weight: bold;
    -fx-text-fill: #243248;
}

.product-card-description {
    -fx-font-size: 13px;
    -fx-text-fill: #6e7d92;
}

.product-card-price {
    -fx-font-size: 16px;
    -fx-font-weight: bold;
    -fx-text-fill: #118a58;
}

.fo-action-button {
    -fx-background-radius: 14;
    -fx-border-radius: 14;
    -fx-padding: 11 18 11 18;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-cursor: hand;
}

.fo-action-primary {
    -fx-background-color: linear-gradient(to right, #6d5dfc, #5b4be9);
    -fx-text-fill: white;
}

.fo-action-primary:hover {
    -fx-opacity: 0.92;
}

.history-search {
    -fx-background-color: white;
    -fx-border-color: #dbe3ea;
    -fx-border-radius: 14;
    -fx-background-radius: 14;
    -fx-padding: 11 14;
    -fx-font-size: 14;
}

.history-results {
    -fx-font-size: 13;
    -fx-text-fill: #6b7280;
    -fx-font-weight: bold;
}

.empty-state {
    -fx-background-color: white;
    -fx-background-radius: 18;
    -fx-border-color: #e7edf6;
    -fx-border-radius: 18;
    -fx-padding: 22;
    -fx-font-size: 14px;
    -fx-text-fill: #5d6b7f;
}

.cart-inline-message {
    -fx-text-fill: #118a58;
    -fx-font-size: 13px;
    -fx-font-weight: bold;
}

.panier-badge {
    -fx-background-color: #d53a4a;
    -fx-text-fill: white;
    -fx-font-size: 11px;
    -fx-font-weight: bold;
    -fx-background-radius: 999;
    -fx-padding: 2 5;
    -fx-min-width: 18;
    -fx-alignment: center;
}

